    /**
     * Label offset (and text-anchor) per city, tuned against the projected pin
     * positions so labels stay readable along the crowded mid-Atlantic /
     * Northeast. Ported from LABEL_OFFSETS in src/components/USMapSVG.tsx.
     *
     * @return array{dx: int, dy: int, anchor: string}
     */
    public static function labelOffset(string $city): array
    {
        $offsets = [
            'Rio Grande Valley' => ['dx' => 10, 'dy' => -2, 'anchor' => 'start'],
            'Honolulu / Hilo' => ['dx' => 10, 'dy' => -8, 'anchor' => 'start'],
            'Lexington' => ['dx' => -10, 'dy' => 11, 'anchor' => 'end'],
            'National Parks' => ['dx' => -10, 'dy' => 14, 'anchor' => 'end'],
            'Charlotte' => ['dx' => 10, 'dy' => 6, 'anchor' => 'start'],
            'Harrisburg' => ['dx' => -10, 'dy' => -6, 'anchor' => 'end'],
            'Omaha' => ['dx' => 10, 'dy' => 4, 'anchor' => 'start'],
            'Billings' => ['dx' => 10, 'dy' => 4, 'anchor' => 'start'],
            'Burlington' => ['dx' => -10, 'dy' => -6, 'anchor' => 'end'],
            'Cincinnati' => ['dx' => -10, 'dy' => 4, 'anchor' => 'end'],
            'Sussex County' => ['dx' => 12, 'dy' => 5, 'anchor' => 'start'],
            'Flagstaff' => ['dx' => -10, 'dy' => 5, 'anchor' => 'end'],
        ];

        return $offsets[$city] ?? ['dx' => 10, 'dy' => 5, 'anchor' => 'start'];
    }
